import{_ as t,o,a,a3 as n}from"./chunks/framework.CnT1yzXN.js";const m=JSON.parse('{"title":"FAQ","description":"Frequently asked questions about Stuzhik. Troubleshooting: OutOfMemoryError, crashes, mod conflicts. Supports Forge, Fabric, NeoForge and Quilt.","frontmatter":{"description":"Frequently asked questions about Stuzhik. Troubleshooting: OutOfMemoryError, crashes, mod conflicts. Supports Forge, Fabric, NeoForge and Quilt.","head":[["meta",{"name":"keywords","content":"stuzhik faq, minecraft launcher problems, outofmemoryerror minecraft, minecraft mods crash, forge fabric quilt neoforge"}]]},"headers":[],"relativePath":"en/faq.md","filePath":"en/faq.md"}'),r={name:"en/faq.md"};function i(s,e,l,h,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="general-questions" tabindex="-1">General questions <a class="header-anchor" href="#general-questions" aria-label="Permalink to &quot;General questions&quot;">​</a></h2><h3 id="how-is-it-different-from-other-launchers" tabindex="-1">How is it different from other launchers? <a class="header-anchor" href="#how-is-it-different-from-other-launchers" aria-label="Permalink to &quot;How is it different from other launchers?&quot;">​</a></h3><p><strong>Crash analysis:</strong> Finds the mods to blame and suggests solutions. Other launchers only show the log.</p><p><strong>Performance:</strong> Fast startup, low resource usage.</p><p><strong>Live monitoring:</strong> Tracks problems while you play.</p><p><strong>Stuzhik Connect:</strong> Direct transfer of modpacks and builds to friends without uploading them to third-party services — see <a href="/en/guide/connect.html">Stuzhik Connect</a>.</p><p><strong>Mod collections:</strong> Sets of mods not tied to a version — applied to any instance with one click, see <a href="/en/guide/collections.html">Mod Collections</a>.</p><h3 id="are-fabric-forge-neoforge-quilt-supported" tabindex="-1">Are Fabric/Forge/NeoForge/Quilt supported? <a class="header-anchor" href="#are-fabric-forge-neoforge-quilt-supported" aria-label="Permalink to &quot;Are Fabric/Forge/NeoForge/Quilt supported?&quot;">​</a></h3><p>Yes, all 4 loaders + Vanilla.</p><h3 id="can-i-use-it-with-existing-instances" tabindex="-1">Can I use it with existing instances? <a class="header-anchor" href="#can-i-use-it-with-existing-instances" aria-label="Permalink to &quot;Can I use it with existing instances?&quot;">​</a></h3><p>Yes. Import from:</p><ul><li>MultiMC/Prism Launcher</li><li>Modrinth modpacks (.mrpack)</li><li>CurseForge modpacks (.zip)</li></ul><h3 id="do-i-need-a-minecraft-account" tabindex="-1">Do I need a Minecraft account? <a class="header-anchor" href="#do-i-need-a-minecraft-account" aria-label="Permalink to &quot;Do I need a Minecraft account?&quot;">​</a></h3><p>Yes, you need to use a Microsoft account that owns Minecraft: Java Edition.</p><h3 id="what-does-stuzhik-send-about-itself" tabindex="-1">What does Stuzhik send about itself? <a class="header-anchor" href="#what-does-stuzhik-send-about-itself" aria-label="Permalink to &quot;What does Stuzhik send about itself?&quot;">​</a></h3><p>Only anonymous statistics, and only with your consent — on first launch the launcher shows the user agreement, and nothing is sent until you answer. Once a day — the launcher version and its channel, the operating system and its bitness, the interface language, &quot;first launch of the day, week, month&quot; marks, the date of the first launch, the invitation code if you came by one, and your answer to &quot;How did you hear about Stuzhik?&quot; if you gave one. While the launcher is open — a short pulse: a random session number (new at every launch) and which Minecraft versions with which loaders are running right now.</p><p>There is no nickname, no accounts, no build names, none of your files and no persistent install identifier; the server doesn&#39;t store IP addresses — it only looks up the country from them. The full list is in the agreement itself. To turn it off: Settings → Privacy → &quot;Send anonymous statistics&quot;; the launcher works the same without it.</p><h3 id="how-do-i-remove-stuzhik-completely" tabindex="-1">How do I remove Stuzhik completely? <a class="header-anchor" href="#how-do-i-remove-stuzhik-completely" aria-label="Permalink to &quot;How do I remove Stuzhik completely?&quot;">​</a></h3><p>Like any program: Windows Settings → Apps → Stuzhik → Uninstall. Service data, saved account logins and the firewall rule always go, while builds and worlds go only if you tick &quot;Also delete builds and worlds (all launcher data)&quot;. More — <a href="/en/guide/installation.html#uninstalling">Uninstalling</a>.</p><h2 id="performance" tabindex="-1">Performance <a class="header-anchor" href="#performance" aria-label="Permalink to &quot;Performance&quot;">​</a></h2><h3 id="why-does-forge-take-so-long-to-install" tabindex="-1">Why does Forge take so long to install? <a class="header-anchor" href="#why-does-forge-take-so-long-to-install" aria-label="Permalink to &quot;Why does Forge take so long to install?&quot;">​</a></h3><p>The Forge installer downloads libraries from <code>maven.minecraftforge.net</code>. This takes 1-3 minutes.</p><p>Stuzhik uses BMCLAPI mirrors to speed this up.</p><h3 id="how-much-space-does-an-instance-take" tabindex="-1">How much space does an instance take? <a class="header-anchor" href="#how-much-space-does-an-instance-take" aria-label="Permalink to &quot;How much space does an instance take?&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Size</th></tr></thead><tbody><tr><td>Minecraft</td><td>~200MB</td></tr><tr><td>Forge/Fabric</td><td>~50MB</td></tr><tr><td>Mods (10-50)</td><td>~100-500MB</td></tr><tr><td><strong>Total</strong></td><td>~400-800MB</td></tr></tbody></table><h3 id="can-i-run-several-instances-at-the-same-time" tabindex="-1">Can I run several instances at the same time? <a class="header-anchor" href="#can-i-run-several-instances-at-the-same-time" aria-label="Permalink to &quot;Can I run several instances at the same time?&quot;">​</a></h3><p>Yes, with no limits.</p><h2 id="mods" tabindex="-1">Mods <a class="header-anchor" href="#mods" aria-label="Permalink to &quot;Mods&quot;">​</a></h2><h3 id="how-do-i-install-a-mod" tabindex="-1">How do I install a mod? <a class="header-anchor" href="#how-do-i-install-a-mod" aria-label="Permalink to &quot;How do I install a mod?&quot;">​</a></h3><p><strong>Option 1:</strong> Catalog</p><ol><li>Open the instance → Mods → Catalog</li><li>Find the mod → Install</li></ol><p><strong>Option 2:</strong> File</p><ol><li>Open the instance → Mods</li><li>The &quot;Add&quot; button or drag &amp; drop a <code>.jar</code></li></ol><h3 id="does-stuzhik-update-mods-automatically" tabindex="-1">Does Stuzhik update mods automatically? <a class="header-anchor" href="#does-stuzhik-update-mods-automatically" aria-label="Permalink to &quot;Does Stuzhik update mods automatically?&quot;">​</a></h3><p>Not by default. You can turn it on for each mod:</p><ol><li>Mod list → click the mod</li><li>Turn on &quot;Auto-update&quot;</li></ol><h3 id="what-do-i-do-about-a-mod-conflict" tabindex="-1">What do I do about a mod conflict? <a class="header-anchor" href="#what-do-i-do-about-a-mod-conflict" aria-label="Permalink to &quot;What do I do about a mod conflict?&quot;">​</a></h3><p>Stuzhik warns you BEFORE installing if it knows about the conflict.</p><p>If a crash has already happened:</p><ol><li>Log Analyzer → finds the mod to blame</li><li>The &quot;Remove mod&quot; or &quot;Replace with a compatible one&quot; button</li></ol><h3 id="where-are-mods-stored" tabindex="-1">Where are mods stored? <a class="header-anchor" href="#where-are-mods-stored" aria-label="Permalink to &quot;Where are mods stored?&quot;">​</a></h3><p>On Windows:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Users\\&lt;username&gt;\\AppData\\Roaming\\ru.sibxodev.stuzhik/instances/&lt;instance_id&gt;/mods/</span></span></code></pre></div><h2 id="stuzhik-connect" tabindex="-1">Stuzhik Connect <a class="header-anchor" href="#stuzhik-connect" aria-label="Permalink to &quot;Stuzhik Connect&quot;">​</a></h2><h3 id="is-it-safe" tabindex="-1">Is it safe? <a class="header-anchor" href="#is-it-safe" aria-label="Permalink to &quot;Is it safe?&quot;">​</a></h3><p>Yes. The connection is encrypted entirely (QUIC with TLS 1.3), the launcher recognizes a friend by a signature made with their key, and a modpack is taken from you only after you click &quot;Allow&quot; (that&#39;s the default; in the &quot;Sharing modpacks&quot; settings, &quot;Ask for permission&quot; can be switched to &quot;Except friends&quot; or &quot;Never&quot;). Executable files are never transferred. More in <a href="/en/guide/connect.html#security">Stuzhik Connect</a>.</p><h3 id="do-i-need-to-open-ports-on-my-router" tabindex="-1">Do I need to open ports on my router? <a class="header-anchor" href="#do-i-need-to-open-ports-on-my-router" aria-label="Permalink to &quot;Do I need to open ports on my router?&quot;">​</a></h3><p>For a local network — no, devices find each other by themselves. For friends outside your network (different homes/cities), a shared VPN is the easiest — then you don&#39;t need to forward ports. In Radmin VPN, ZeroTier and Hamachi, discovery works like on a LAN; in Tailscale, you add your friend by address once, and after that the launcher finds them by itself. On Windows you need one firewall rule, &quot;Stuzhik Connect&quot; — the button in the &quot;Friends&quot; section adds it.</p><h3 id="does-it-work-directly-over-the-internet-without-a-vpn" tabindex="-1">Does it work directly over the internet, without a VPN? <a class="header-anchor" href="#does-it-work-directly-over-the-internet-without-a-vpn" aria-label="Permalink to &quot;Does it work directly over the internet, without a VPN?&quot;">​</a></h3><p>No, if you&#39;re on different networks. Stuzhik has no server of its own for connecting over the internet — it finds and connects devices only within one network (real, or virtual through a VPN). If you&#39;re physically on the same LAN, it just works; if not, you need a shared VPN, see <a href="/en/guide/connect.html#if-you-are-on-different-networks">Stuzhik Connect</a>.</p><h2 id="problems" tabindex="-1">Problems <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Problems&quot;">​</a></h2><h3 id="outofmemoryerror" tabindex="-1">OutOfMemoryError <a class="header-anchor" href="#outofmemoryerror" aria-label="Permalink to &quot;OutOfMemoryError&quot;">​</a></h3><p><strong>Cause:</strong> Not enough RAM allocated.</p><p><strong>Solution:</strong></p><ol><li>Open the instance → Edit</li><li>Increase RAM (4-6GB recommended for modpacks)</li><li>Save → Restart</li></ol><h3 id="the-game-won-t-launch" tabindex="-1">The game won&#39;t launch <a class="header-anchor" href="#the-game-won-t-launch" aria-label="Permalink to &quot;The game won&#39;t launch&quot;">​</a></h3><p><strong>Check:</strong></p><ol><li>Dev Console → are there any errors?</li><li>Log Analyzer → finds the problem automatically</li><li>Is Java installed? (Stuzhik installs it automatically, but something may have gone wrong)</li></ol><h3 id="mods-don-t-load" tabindex="-1">Mods don&#39;t load <a class="header-anchor" href="#mods-don-t-load" aria-label="Permalink to &quot;Mods don&#39;t load&quot;">​</a></h3><p><strong>For Forge:</strong></p><ul><li>The file must be for Forge (<code>-forge-</code> in the name)</li><li>The Minecraft version must match</li></ul><p><strong>For Fabric:</strong></p><ul><li>Fabric API is required (installed automatically)</li><li>The file is for Fabric (<code>-fabric-</code> in the name)</li></ul><h3 id="crash-mentioning-mixin" tabindex="-1">Crash mentioning &quot;Mixin&quot; <a class="header-anchor" href="#crash-mentioning-mixin" aria-label="Permalink to &quot;Crash mentioning &quot;Mixin&quot;&quot;">​</a></h3><p><strong>Cause:</strong> A conflict between mods that modify the same code.</p><p><strong>Solution:</strong></p><ol><li>Log Analyzer shows the conflicting mods</li><li>Remove one of the conflicting mods</li><li>Or use an alternative mod</li></ol><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><h3 id="how-do-i-report-a-bug-or-suggest-a-feature" tabindex="-1">How do I report a bug or suggest a feature? <a class="header-anchor" href="#how-do-i-report-a-bug-or-suggest-a-feature" aria-label="Permalink to &quot;How do I report a bug or suggest a feature?&quot;">​</a></h3><p>Write to us on <a href="https://t.me/stuzhik_launcher" target="_blank" rel="noreferrer">Telegram</a> — that&#39;s also where update announcements are posted.</p>',71)])])}const f=t(r,[["render",i]]);export{m as __pageData,f as default};
